<script setup lang="ts">
import { ref,onMounted,computed } from 'vue';
import '~/assets/css/roman-lab.css';
import { readRecords,readShots,comparable,download } from '../../lab/comparison/storage';
import type { Measurement,Shot } from '../../lab/comparison/storage';
import type { EngineId } from '../../lab/shared/types';
useHead({bodyAttrs:{class:'has-roman-lab'},title:'3D Engine Lab · ローマの箱庭 | MIRAI MUSEUM',meta:[{name:'description',content:'同じ小さなローマを、ふたつの描画エンジンで。Three.js と Babylon.js の映像、ゲーム体験、実測を比較する実験ギャラリー。'}]});
const records=ref<Measurement[]>([]);
const shots=ref<Partial<Record<EngineId,Shot>>>({});
const comparison=ref<'fair'|'maximum'>('fair');
onMounted(()=>{records.value=readRecords();shots.value=readShots();});
const latest=(engine:EngineId)=>[...records.value].reverse().find(r=>r.engine===engine && r.comparison===comparison.value);
const pair=computed(()=>{const a=latest('three'),b=latest('babylon');return a && b?comparable(a,b):false;});
const display=(engine:EngineId,k:'fps'|'frameMs'|'drawCalls'|'triangles'|'textures'|'loadMs')=>{const m=latest(engine);if(!m)return '未測定';const n=m[k];return n===null?'計測不可':n.toLocaleString('ja-JP',{maximumFractionDigits:['fps','frameMs'].includes(k)?2:0});};
function exportRecords(){download(new Blob([JSON.stringify(records.value,null,2)],{type:'application/json'}),'mirai-engine-comparison.json');}
const shotMatch=computed(()=>{const a=shots.value.three,b=shots.value.babylon;return a && b && JSON.stringify(a.camera)===JSON.stringify(b.camera) && JSON.stringify(a.settings)===JSON.stringify(b.settings) && a.fountain===b.fountain && a.resolution===b.resolution;});
</script>
<template>
  <div class="lab-comparison">
    <header class="lab-header"><NuxtLink to="/" class="lab-brand"><span class="lab-brand-symbol"><LabIcon name="museum" /></span><span>MIRAI MUSEUM<small>EXPERIMENTAL GALLERY / 01</small></span></NuxtLink><span class="lab-index-tag">3D ENGINE STUDY · 2026</span><NuxtLink to="/lab/three" class="lab-report-link">箱庭を開く<LabIcon name="arrow" /></NuxtLink></header>
    <main class="lab-index-main">
      <section class="lab-index-hero"><div class="lab-overline"><span /> THE SAME WORLD. TWO PERSPECTIVES.</div><h1>A small world,<br><em>an endless possibility.</em></h1><p class="lab-index-lead">小さな世界から、未来の博物館へ。</p><p class="lab-index-description">水道橋の影、風に揺れる木々、広場に集う人々。<br>同じローマの街を、ふたつの3Dエンジンで巡る。<br>映像の美しさと、触れる楽しさを確かめるための実験室。</p><div class="lab-index-hero-actions"><NuxtLink to="/lab/three" class="lab-primary">街を探索する<LabIcon name="arrow" /></NuxtLink><a href="#compare">比較の条件を読む ↓</a></div><div class="lab-index-art"><img :src="'/lab/three-day.webp'" alt="石造りの神殿と水道橋、赤い屋根の住宅、川辺をまとめた古代ローマのミニチュア" fetchpriority="high" /><span>ROMA · CITY OF WATER</span></div></section>
      <section class="lab-index-engines"><div class="lab-section-intro"><span class="lab-overline">01 / EXPERIENCE</span><h2>ひとつの街、ふたつの入り口。</h2><p>UI・ルール・モデルは共通。各エンジンを個別に起動します。</p></div><div class="lab-engine-cards"><NuxtLink to="/lab/three" class="lab-engine-card"><span class="lab-engine-number">A</span><div><span class="lab-overline">RENDERING LIBRARY</span><h3>Three.js</h3><p>描画を細かく組み立てる。<br>自由な表現のための、軽やかな道具箱。</p><span class="lab-card-cta">Three.jsで開く<LabIcon name="arrow" /></span></div><LabIcon name="orbit" /></NuxtLink><NuxtLink to="/lab/babylon" class="lab-engine-card"><span class="lab-engine-number">B</span><div><span class="lab-overline">INTEGRATED 3D ENGINE</span><h3>Babylon.js</h3><p>描画とゲームの機能をつなぐ。<br>遊べる展示のための、統合された基盤。</p><span class="lab-card-cta">Babylon.jsで開く<LabIcon name="arrow" /></span></div><LabIcon name="compass" /></NuxtLink></div></section>
      <section id="compare" class="lab-comparison-section"><div class="lab-section-intro"><span class="lab-overline">02 / A FAIR COMPARISON</span><h2>同じ条件から、違いを見つける。</h2></div><div class="lab-condition-grid"><article><span class="lab-condition-letter">A</span><h3>公平な共通条件</h3><p>同一GLB・HDR・カメラ・PBR・固定解像度・影のサイズ。共通の移動、衝突、アニメーション、パズルを使用します。</p><small>WebGL 2 · ACES · MSAA · PCF shadows</small></article><article><span class="lab-condition-letter">B</span><h3>最大品質</h3><p>同じ世界に、それぞれのAOとBloomを追加。最高画質での表現と負荷を確認します。Aの計測とは区別します。</p><small>Three: SSAOPass / Babylon: SSAO2 + Default pipeline</small></article></div><div class="lab-feature-table-wrap"><table class="lab-feature-table"><thead><tr><th>このプロトタイプの実装</th><th>Three.js</th><th>Babylon.js</th></tr></thead><tbody><tr><td>共通3Dモデル</td><td>GLTFLoader</td><td>glTF loader / ImportMeshAsync</td></tr><tr><td>PBR・環境光</td><td>MeshStandardMaterial / PMREM</td><td>PBRMaterial / HDRCubeTexture</td></tr><tr><td>カメラ・衝突・移動</td><td colspan="2">共通TypeScript · A* 経路探索 · 固定時間刻み</td></tr><tr><td>探索・調査・水路パズル</td><td colspan="2">同じVue UIとゲームルール · 5つの発見</td></tr><tr><td>住民・風・水・舟</td><td colspan="2">共通アニメーションデータ · インスタンスによる水の演出</td></tr><tr><td>必要な物理演算</td><td colspan="2">このゲームは共通の軽量な衝突判定で成立。剛体エンジンは未導入。</td></tr></tbody></table></div></section>
      <section class="lab-comparison-section"><div class="lab-section-intro"><span class="lab-overline">03 / MEASURED, NOT ASSUMED</span><h2>あなたの環境で、測る。</h2><p>各箱庭の計測パネルから「同条件で10秒計測」。このブラウザの記録を表示します。</p></div><div class="lab-measure-bar"><div class="lab-mode-tabs"><button :class="{'is-active':comparison==='fair'}" @click="comparison='fair'">A · 共通条件</button><button :class="{'is-active':comparison==='maximum'}" @click="comparison='maximum'">B · 最大品質</button></div><button :disabled="!records.length" @click="exportRecords">記録をJSONで保存 ↓</button></div><div class="lab-feature-table-wrap"><table class="lab-feature-table lab-numeric-table"><thead><tr><th>実測項目</th><th>Three.js</th><th>Babylon.js</th></tr></thead><tbody><tr><td>FPS</td><td>{{display('three','fps')}}</td><td>{{display('babylon','fps')}}</td></tr><tr><td>平均フレーム時間 / ms</td><td>{{display('three','frameMs')}}</td><td>{{display('babylon','frameMs')}}</td></tr><tr><td>Draw calls</td><td>{{display('three','drawCalls')}}</td><td>{{display('babylon','drawCalls')}}</td></tr><tr><td>三角形数 ※</td><td>{{display('three','triangles')}}</td><td>{{display('babylon','triangles')}}</td></tr><tr><td>テクスチャ数 ※</td><td>{{display('three','textures')}}</td><td>{{display('babylon','textures')}}</td></tr><tr><td>初期ロード / ms</td><td>{{display('three','loadMs')}}</td><td>{{display('babylon','loadMs')}}</td></tr><tr><td>GPUメモリ・消費電力</td><td>計測不可</td><td>計測不可</td></tr></tbody></table></div><p class="lab-measure-match">{{pair?'同じ解像度・画質・昼夜・視点・ブラウザの記録です。':'条件が一致した両エンジンの測定記録は、まだありません。'}}</p><p class="lab-footnote">目標はPC 60fps・スマートフォン30fps以上。実測前に達成とは表示しません。※ Threeはrenderer.infoの影・ポスト処理を含む描画統計、Babylonの三角形数は主カメラのactiveIndices / 3です。テクスチャ数はGPU割当 / InternalTextureキャッシュ。数値の定義が異なるため直接同一視できません。初期ロードはモジュール読込開始から初回描画完了までで、キャッシュ条件に影響されます。</p></section>
      <section class="lab-comparison-section"><div class="lab-section-intro"><span class="lab-overline">04 / LOOK CLOSER</span><h2>光と影を、見比べる。</h2><p>撮影は両エンジン共通の1440 × 960。PNGとカメラ条件JSONをダウンロードできます。</p></div><div class="lab-shot-grid"><figure><img :src="shots.three?.image || '/lab/three-day.webp'" alt="Three.js版のローマ箱庭" loading="lazy" /><figcaption><strong>Three.js</strong><span>{{shots.three?'このブラウザで撮影':'開発環境の共通視点 · 昼'}}</span></figcaption></figure><figure><img :src="shots.babylon?.image || '/lab/babylon-day.webp'" alt="Babylon.js版のローマ箱庭" loading="lazy" /><figcaption><strong>Babylon.js</strong><span>{{shots.babylon?'このブラウザで撮影':'開発環境の共通視点 · 昼'}}</span></figcaption></figure></div><p v-if="shots.three || shots.babylon" class="lab-footnote">{{shotMatch?'撮影時の視点・画質・昼夜は一致しています。':'保存した画像の撮影条件は一致していません。条件JSONを確認してください。'}}アニメーションの時刻はJSONに記録しています。</p></section>
      <section class="lab-index-ending"><span class="lab-overline">THE NEXT HUNDRED WORLDS</span><h2>展示を、体験へ。</h2><p>古代都市から、自然、宇宙、科学の世界まで。<br>共通のアセットとルールを、次の100の箱庭へ。</p><NuxtLink to="/lab/babylon" class="lab-primary">Babylon.js版を体験する<LabIcon name="arrow" /></NuxtLink><details><summary>実装と選定の記録</summary><p>詳しい比較、計測環境、検証範囲、変更量と選定の根拠はリポジトリの <code>docs/three-vs-babylon.md</code> に記録しています。スマートフォン実機の結果は、ブラウザのタッチエミュレーションとは区別して評価します。</p></details></section>
    </main><footer class="lab-index-footer"><span>MIRAI MUSEUM · EXPERIMENTAL GALLERY</span><span>ROMAN MINIATURE / ORIGINAL ASSETS · CC0</span></footer>
  </div>
